// Main UI font: Roboto Condensed (SIL OFL, full Vietnamese incl. ₫; ✓/✗ merged in from Arial Unicode).
// Condensed = narrower glyphs → more text per line / less truncation on the 466px round screen. Two weights:
// Geist — Regular for body/labels, Medium for names, titles and emphasis. Generated by
// scripts/gen_fonts.sh from the TTFs vendored under fonts/; see the `Opts:` header inside any of these
// files for the exact lv_font_conv invocation, and regenerate rather than hand-editing.
//
// A family swap ONLY: the five sizes are the ones the Roboto Condensed set used, so every call site kept
// its meaning and this was a rename. Geist is a normal-width proportional face where Roboto Condensed was
// a narrow one — measured, 0.534 em against 0.453 em average ASCII advance, so every line is ~18% longer
// than the surrounding geometry was tuned for. Those clip limits and max_widths are deliberately untouched.
//
// LVGL's Montserrat faces stay linked for LV_SYMBOL_* only: those are private-use codepoints that exist in
// no other font, so a label carrying one keeps a Montserrat face or its glyph draws as an empty box.
extern const lv_font_t geist_reg_16;
extern const lv_font_t geist_reg_20;
extern const lv_font_t geist_reg_24;  // small labels / muted meta
extern const lv_font_t geist_reg_25;  // main body: project-screen content, event cards, settings rows
extern const lv_font_t geist_med_28;
extern const lv_font_t geist_med_32;  // titles, section headers, agent name in the reader, status verb
extern const lv_font_t geist_reg_32;
extern const lv_font_t geist_reg_34;
extern const lv_font_t geist_reg_38;  // large body: reader detail, "No activity" placeholder, the "+" glyph
extern const lv_font_t geist_med_38;
extern const lv_font_t geist_med_48;
extern const lv_font_t geist_med_64;  // DIGITS ONLY (0-9 and space) — the Overview's agent count, nothing else
// The only SemiBold on the device: the reset confirm's primary, which the design sets one weight
// above its neighbours to mark it as the safe, committing action.
extern const lv_font_t geist_sem_24;  // largest display: tile agent name + overview agent count

// Round 466x466 AMOLED: keep ALL content inside the inscribed square (~330px, r·√2) and CENTRE it,
// so nothing reaches the curved edge. 330px is the widest column whose corners never clip; centred
// text makes the side margins read as intentional. Both axes centred + short content = stays in the
// circle's safe band (no top/bottom arc clip).
#define SCREEN_PAD   18
#define SAFE_CONTENT_W 384       // centred column for readable content — wide, since content sits in the
                                 // circle's mid band where the usable width is much larger than the inscribed square
// The Overview's seats (mockup/overview-v3.html, "H · Halo, no ring"). FIXED, not a growing column: nothing
// moves when the status changes, the words change. Every number is a device pixel on the 466 face; the far
// corner of every control is inside the 233px rim, above the home-swipe band (y ≥ 400) and below the
// notification pull-down band (y < 90).
//
// The shape follows what round devices agree on — the centre is one number, the lower arc is for the
// hand: Inbox · Voice · Settings on one arc, Voice larger and on the axis, wearing the same 44px mic the
// agent tile wears. Goal and Loop are gone from this face: they are ways of speaking, not things to see.
#define OV_ROW_Y      118   // "8 agents" on one baseline: the count in the 64px digits face, the word at 38
#define OV_NUM_H      72    // the row's height — the digit's line box
#define OV_ROW_GAP    14    // between the digit and the word
#define OV_STATUS_Y   204   // "N working" / "All idle", Geist 38
#define OV_SIDE_D     64    // Inbox and Settings: 64px rounds, 30px glyphs, centred on y=340
#define OV_BELL_X     78
#define OV_GEAR_X     324
#define OV_SIDE_Y     308
// Voice: an 88px round on the axis, no caption (owner: "bỏ chữ Voice luôn, icon là đủ") — the caption's
// height went to the button — and dropped 50px below the sides (centre y=390; owner, twice: 10 then 30
// more) so the three follow the bezel the way the old arc did, the middle one nearest the resting thumb.
// Its lowest point is 434, 201px from the centre, 32px inside the rim. Its lower third is in the home
// band: a tap there is a tap, and a swipe up that starts on it is the button's, so the home gesture is
// made from beside it, as it always was with a button on the axis.
#define OV_VOICE_D    88
#define OV_VOICE_X    189
#define OV_VOICE_Y    346
#define SAFE_W       lv_pct(72)  // ~335px — wrapped text on the side screens stays inside the curve
// MAX_PROJECTS comes from commander_client.h (shared with app_main's fetch buffers) so the UI tile
// array and the WS fetch never disagree; the UI keeps only a shell per project + a materialized window.
#define MAX_EVENTS   1      // tile shows only the latest event (the most recent summary)
#define TODO_VISIBLE_ROWS 4 // todo checklist shows this many rows; the rest scroll (keeps status on screen)
#define AGENTS_VISIBLE_ROWS 3 // sub-agent list shows this many rows; the rest scroll (coexists with the tool line)
#define BUSY_DOTS    3      // "processing" indicator = this many blinking dots (a loading animation)
#define PREVIEW_BYTES 220   // tile teaser length (bytes, UTF-8 safe) — one card has room for a longer
                            // tease; full text still via tap-to-read

#define COL_BG     lv_color_hex(0x000000)
#define COL_FG     lv_color_hex(0xeaeaf0)
#define COL_MUTED  lv_color_hex(0x8a8a99)
#define COL_GREEN  lv_color_hex(0x35c46a)
#define COL_VOICE     lv_color_hex(0x00ff2f)   // Figma "Section final": voice waveform + active sparkle green
// The E2EE pairing digits. Sampled from the owner's reference render, NOT from the Figma file: the file's
// text fill on that frame is COL_VOICE and the render is this — a lighter, softer green. Following the
// render was the explicit instruction, and it is also the better call on this panel, where the pure hue at
// 40px is the harshest thing on screen. Deliberately not reused elsewhere; the code pills stay COL_VOICE.
#define COL_PAIRCODE  lv_color_hex(0x75f958)
#define COL_SPARK_OFF lv_color_hex(0xffffff)   // Figma "Section final": idle sparkle white (sweeps white↔green)
#define COL_DOT_OFF   lv_color_hex(0x4c4c4c)   // Figma overview: inactive page-dot grey + MACHINE eyebrow
#define COL_INK_LOW   lv_color_hex(0x5e5e6c)   // "present but dead" — how a disabled control is dimmed, since
                                               // lv_obj_set_style_opa() forces a temp layer (see display.c)
#define COL_RED    lv_color_hex(0xff5a5a)
#define COL_ACCENT lv_color_hex(0x5b8cff)
#define COL_YELLOW lv_color_hex(0xf0b429)
#define COL_ORANGE lv_color_hex(0xff8a4c)   // working-status verb row
#define COL_CLAUDE lv_color_hex(0xcc7c5e)   // matches the shared Claude reference color
#define COL_CARD   lv_color_hex(0x16161c)
// Settings tile (Figma redesign): navy bg + pill rows + blue icon in a dark circle.
#define COL_SET_BG   lv_color_hex(0x000000)   // settings tile background + icon circle (black, per new Figma)
#define COL_SET_PILL lv_color_hex(0x1c1c1c)   // settings row pill fill (dark grey)
#define COL_SET_BORD lv_color_hex(0x333333)   // settings pill border
#define COL_SET_BLUE lv_color_hex(0x006fff)   // the "Keep it" primary on the reset confirm (Figma)
// AskUserQuestion option pill (Figma "Question" / "Question — multi-select", node 15:6121 / 15:6135).
// Its own value, not COL_SET_PILL: the settings pill is 0x1c1c1c and this is deliberately far lighter —
// a settings row sits in a list you are reading, an option is a target you are about to hit, and the
// design separates them on exactly that.
#define COL_Q_PILL   lv_color_hex(0x33353c)

// Settings list geometry (Figma): uniform rows, stacked contiguously, four of them inside the round face.
// 320 wide only fits the circle between y~64 and y~402 — 338px, i.e. exactly four 84px rows, which is why
// the fifth has to be scrolled to rather than squeezed in.
#define SET_ROW_W    320
#define SET_ROW_H    84
#define SET_LIST_PAD 65    // first row starts where the design puts it; the list scrolls by one row
// The label font of a settings row, referenced ONCE so the one-line height pin, the default trailing
// font and the baseline nudge can never drift from it — they did, and a 32px label ended up pinned
// into a 28px box.
#define SET_ROW_FONT (&geist_reg_32)
#define COL_SET_ICON lv_color_hex(0xffffff)   // settings row icon (white, per New Setting Figma)
#define COL_BRIGHT   lv_color_hex(0x059600)   // brightness fill — the green the Figma track starts from

