// GOAL and LOOP are modifiers on the utterance you are ABOUT to speak — the voice_start header carries
// the flag and the backend prepends "/goal " or "/loop ". They used to live in a SELECT that held a value
// between taps, which cost a tap, a whole picker screen, a pick and a trip back before the Voice press
// that actually started anything. They are now three plain buttons, as on the square: each one starts the
// recording in its own mode, so nothing is held between turns and there is no state to fall back from.
static uint32_t s_voice_start_ms;   // lv_tick at capture start → drives the normal 10-minute watchdog
static uint32_t s_voice_max_ms = 600000u; // backend quota status can shorten the normal 10-minute cap
// Silence auto-stop, DISABLED. Flip to 1 to bring it back: a recording with no speech (audio_client_heard_voice,
// an RMS gate calibrated at meanabs>600 over 4 CONSECUTIVE chunks — 350 false-latched on this mic's noise floor)
// within VOICE_SILENCE_MS was discarded, so an accidental Voice press couldn't sit recording for 10 minutes.
#define VOICE_SILENCE_AUTOSTOP 0
#define VOICE_SILENCE_MS 15000u
static void ui_voice_discard_silent(void);   // fwd: silent auto-abort teardown (defined below)
// Overview ROUTE voice: true from route-capture start until the router answers (voice_routed / empty / error /
// watchdog). While set we KEEP the "Sending…" loading overlay up AFTER the upload finishes — the router is still
// choosing an agent — so the user sees it working instead of the UI snapping back to a static Overview.
// True while the MAC is doing the listening for us. The dial holds no audio and has nothing to upload, so
// stopping means telling the peer to finish — not tearing down a capture that never started here.
static bool s_voice_routing;
static uint32_t s_voice_route_ms;   // lv_tick when the upload finished (routing wait begins) → routing watchdog
#define VOICE_ROUTE_WAIT_MS 60000   // release the loading overlay if the router never answers (STT of a long
                                    // ramble buffer + the voice_route RPC — generous for ~10-min recordings)
