// WHICH WAY A DRAG MOVES THE SCROLLBACK.
//
// Held here, in RAM, and read by touch.c on every reporting window — the alternative is an NVS read inside
// the scroll path, which is the one path on this device that must not touch flash. NVS is where this
// SURVIVES a reboot, not where it is consulted.
//
// Two words for the two habits, and neither is "on": "Natural" is the text following the finger (drag up
// and the page goes up with it, the way a sheet of paper does), "Reversed" is the view following it (drag
// up and the text comes down, the way a scrollbar does). A row saying On/Off would be asking about a
// setting rather than about the hand.
static bool s_scroll_reversed;
