static bool s_overview_active;       // true while the leading overview tile (ring 0) is the visible page
static char s_voicelang[CFG_VLANG_MAX];       // "vi" | "en" — cached, mirrors NVS

// Settings > Voice languages. `code` is what voice_start carries and what the backend gates on
// (VOICE_LANGS in autonomous-harness-backend/src/lib/deepgram.ts) — the two lists must be edited together, or a
// language offered here is silently rewritten there.
//
// Labels are ASCII endonyms-in-English ON PURPOSE. The bundled Geist faces carry Latin + Vietnamese and
// no CJK, so "\u65e5\u672c\u8a9e" would render as empty boxes; "Espa\u00f1ol" and "Fran\u00e7ais" would render
// (those accents are in range) but then Japanese would be the one odd row. One glyph set, one look.
static const struct { const char *code; const char *label; } LANGS[] = {
    { "en", "English" },
    { "vi", "Vietnamese" },
    { "es", "Spanish" },
    { "fr", "French" },
    { "ja", "Japanese" },
    { "it", "Italian" },
};
#define N_LANGS ((int)(sizeof(LANGS) / sizeof(LANGS[0])))

/** Index of the stored language in LANGS, or 0 (English) when it is unset or no longer offered. */
static int vlang_index(void)
{
    for (int i = 0; i < N_LANGS; i++) if (strcmp(s_voicelang, LANGS[i].code) == 0) return i;
    return 0;
}

